import {parseRoute,filterProducts,escapeHtml as esc} from './core.js?v=belgravia-1';
import {initContact,syncScroll} from './contact.js';
import {cataloguePhoto,photoButton,referenceCard,featuredReferences} from './catalogue-photos.js?v=belgravia-1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let manifest,activeCollection='belgravia',category='all',gallery,galleryModule,routeSerial=0,noticeTimer,lastImageTrigger;
window.atelier={ready:false,get collection(){return activeCollection},get route(){return parseRoute(location.hash)},get data(){return manifest}};
const collection=id=>manifest.collections.find(c=>c.id===id);
const motion=()=>matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth';
function setupCollections(){
 for(const id of['gallery-collection','viewer-collection'])$('#'+id).replaceChildren(...manifest.collections.map(c=>new Option(c.name,c.id)));
 $('#product-collection').replaceChildren(new Option('All collections','all'),...manifest.collections.filter(c=>c.productCount).map(c=>new Option(c.name,c.id)));
 $('.hero-tabs').replaceChildren(...manifest.collections.map(c=>{const b=document.createElement('button');b.dataset.hero=c.id;b.setAttribute('aria-pressed','false');b.innerHTML=esc(c.number)+' <span>'+esc(c.id==='walnut'?'Walnut':c.name)+'</span>';return b;}));
}
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({block:'start',behavior:'instant'});});
function notify(message){clearTimeout(noticeTimer);$('#notification').textContent=message;$('#notification').hidden=false;noticeTimer=setTimeout(()=>$('#notification').hidden=true,4500);}
function closeMenu(){$('#main-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle span').textContent='＋';}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#menu-toggle').getAttribute('aria-expanded')!=='true';$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#main-nav').classList.toggle('open',open);$('#menu-toggle span').textContent=open?'−':'＋';});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
initContact();
function cards(){const html=manifest.collections.map(c=>`<article class="collection-card"><a class="cover" href="#/collections/${c.id}" aria-label="Explore ${esc(c.name)}"><img src="${c.hero}" alt="${esc(c.name)} — original Blender render" loading="lazy" width="960" height="1080"><span class="cover-index">${c.number} / ${c.kind.toUpperCase()}</span><span class="cover-arrow" aria-hidden="true">↗</span></a><div class="card-caption"><p class="eyebrow">${esc(c.finish)}</p><h3><a href="#/collections/${c.id}">${esc(c.name)}</a></h3><p>${esc(c.tagline)}</p><div class="card-links"><a href="#/collections/${c.id}">Explore the collection ↗</a><a href="#/gallery/${c.id}?load=1">Enter in 3D ↗</a></div></div></article>`).join('');$$('[data-collection-cards]').forEach(el=>el.innerHTML=html);}
function setHero(id){const c=collection(id);$('#hero-image').src=c.hero;$('#hero-image').alt=c.name+' — original Blender render';$('#hero-caption').textContent=c.number+' / '+c.name.toUpperCase()+' — '+c.tagline.toUpperCase();$$('[data-hero]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.hero===id)));}
function imageButton(r,index){return `<button class="render-card" data-image="${esc(r.image)}" data-caption="${esc(r.title+' / '+r.caption)}" data-request="${esc(r.request)}"><img src="${r.image}" alt="${esc(r.title)} — original Blender render" loading="lazy" width="960" height="540"><span>${String(index+1).padStart(2,'0')} / ${esc(r.title)}<i>View image ↗</i></span></button>`;}
function fileButton(f){return `<button data-download-request="${esc(f.request)}"><span><b>${esc(f.title)}</b><small>${esc(f.description)}</small></span><span>${esc(f.extension)} ↗</span></button>`;}
function renderCollection(c){activeCollection=c.id;$('#collection-hero').src=c.hero;$('#collection-hero').alt=c.name+' — original Blender render';$('#collection-kind').textContent=c.kind+' / 2026';$('#collection-title').textContent=c.name;$('#collection-tagline').textContent=c.tagline;$('#collection-number').textContent=c.number+' / THE COLLECTION';$('#collection-heading').textContent=c.title;$('#collection-description').textContent=c.description;$('#collection-finish').textContent=c.finish+' · '+(c.productCount?c.productCount+' catalogue pieces · '+c.placementCount+(c.layout==='furnished-interior'?' interior placements':' exhibition placements'):'Independent bedroom study');$('#collection-tour').href='#/gallery/'+c.id+'?load=1';$('#collection-products').hidden=!c.productCount;$('#collection-products').href='#/products?collection='+c.id;$('#collection-renders').innerHTML=c.renders.map(imageButton).join('');$('#collection-files').innerHTML=c.files.map(fileButton).join('');}
function renderProducts(){const list=filterProducts(manifest.products,{collection:$('#product-collection').value,category,query:$('#product-search').value});$('#product-count').textContent=list.length+' / '+manifest.products.length+' pieces';$('#products').innerHTML=list.map(p=>`<article class="product-card" data-sku="${esc(p.sku)}">${photoButton(p,'catalogue-photo product-image')}<span class="sku">${esc(p.collectionName)} / ${esc(p.sku)}</span><h3><a href="${esc(cataloguePhoto(p).inspect)}">${esc(p.name)}</a></h3><span class="dimension">${p.dimensions.join(' × ')} mm</span><a class="text-link product-inspect" href="${esc(cataloguePhoto(p).inspect)}" aria-label="Inspect in 3D: ${esc(p.name+', '+p.sku)}">Inspect in 3D <span>↗</span></a></article>`).join('');$('#no-products').hidden=list.length>0;$$('[data-category]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.category===category));b.hidden=b.dataset.category!=='all'&&!manifest.products.some(p=>p.category===b.dataset.category);});}
function renderReferences(c){$('#collection-room-reference').hidden=!c.roomReferences?.length;$('#room-reference-grid').innerHTML=(c.roomReferences||[]).map((r,i)=>`<button class="render-card" data-image="${esc(r.image)}" data-caption="${esc(r.title+' / Original catalogue image. '+r.caption)}" data-request="${esc('the '+c.name+' original '+r.title+' catalogue reference and reconstructed interior')}" data-request-label="Ask about this room"><img src="${esc(r.image)}" alt="${esc(r.title)} — original MARINER catalogue composition" loading="lazy" width="1591" height="1126"><span>${String(i+1).padStart(2,'0')} / ${esc(r.title)}<i>View original reference ↗</i></span></button>`).join('');const pieces=manifest.products.filter(p=>p.collection===c.id);$('#collection-reference').hidden=!pieces.length;$('#collection-reference-grid').innerHTML=featuredReferences(manifest.products,c.id).map(referenceCard).join('');$('#collection-reference-all').href='#/products?collection='+c.id;$('#collection-reference-source').textContent=pieces.length?cataloguePhoto(pieces[0]).source+' / '+cataloguePhoto(pieces[0]).brand+'. Original catalogue images and this website’s reconstructed renders are distinct sources.':'';}
function renderMaterialReferences(c){const pieces=featuredReferences(manifest.products,c.id);$('#material-reference').hidden=!pieces.length;$('#material-reference-grid').innerHTML=pieces.map(referenceCard).join('');$('#material-reference-all').href='#/products?collection='+c.id;$('#material-render-heading').hidden=!pieces.length;if(pieces.length){const photo=cataloguePhoto(pieces[0]);$('#material-reference .source-note').textContent='Source: '+photo.source+' / '+photo.brand+'. Original catalogue images, not verified physical material-sample photographs. Confirm construction and finish with the supplier; colour and grain vary with lighting, screens and materials.';}}
function renderProductReference(sku){const p=manifest.products.find(x=>x.sku===sku),panel=$('#gallery-reference');panel.hidden=!p;if(!p)return;const photo=cataloguePhoto(p);$('#gallery-reference-image').innerHTML=photoButton(p);$('#reference-name').textContent=p.name;$('#reference-sku').textContent=p.collectionName+' / '+p.sku;$('#reference-finish').textContent=p.finish;$('#reference-dimensions').textContent=p.dimensions.join(' × ')+' mm · width × depth × height';$('#reference-source').textContent=photo.source+' / '+photo.brand+'. '+photo.note;const b=$('#selected-photo');Object.assign(b.dataset,{image:photo.image,caption:photo.caption,request:photo.request,requestLabel:'Ask about this piece',inspect:photo.inspect,photoSku:p.sku});b.setAttribute('aria-label','View catalogue photo: '+p.name+', '+p.sku);}
document.addEventListener('atelier:selection',e=>renderProductReference(e.detail.sku));
$('#reference-to-3d').addEventListener('click',()=>{$('#viewer').focus({preventScroll:true});$('#viewer-stage').scrollIntoView({block:'start',behavior:motion()});});
function renderMaterials(id){const c=collection(id);activeCollection=id;$('#material-tabs').innerHTML=manifest.collections.map(x=>`<button data-material="${x.id}" aria-pressed="${x.id===id}">${x.number} / ${esc(x.name)}</button>`).join('');$('#material-story').innerHTML=`<h2>${esc(c.name)}</h2><p>${esc(c.description)}</p>`;$('#material-grid').classList.toggle('single',c.materials.length===1);$('#material-grid').innerHTML=c.materials.map(m=>`<button class="material-card" data-image="${m.image}" data-caption="${esc(c.name+' / '+m.title+' — '+m.description)}" data-request="${esc('the original '+c.name+' material detail render: '+m.title)}"><img src="${m.image}" alt="${esc(m.title)} — original Blender render detail" width="1200" height="1400" loading="lazy"><div><h3>${esc(m.title)} <span aria-hidden="true">↗</span></h3><p>${esc(m.description)}</p></div></button>`).join('');}
function renderStudio(){$('#studio-files').innerHTML=manifest.collections.map(c=>`<article class="studio-file-card"><p class="eyebrow">${c.number} / ${c.kind.toUpperCase()}</p><h3>${esc(c.name)}</h3><p>${esc(c.finish)}<br>${c.productCount?c.productCount+' catalogue pieces':'Complete room study'} · Native Blender, GLB & original renders</p><button class="button" data-download-request="${esc('the complete '+c.name+' project: native Blender scene, GLB models, original renders and source files')}">Request ${esc(c.name)} <span>↗</span></button></article>`).join('');}
async function ensureGallery(){if(!galleryModule)galleryModule=import('./gallery.js?v=belgravia-1');const mod=await galleryModule;if(!gallery){gallery=mod.createGallery({onNotice:notify});window.atelier.gallery=gallery;}return gallery;}
async function route(){if(!manifest)return;const serial=++routeSerial,r=parseRoute(location.hash);closeMenu();if(r.page!=='gallery')gallery?.setActive(false);$$('main>[data-page]').forEach(el=>el.hidden=el.dataset.page!==r.page);const navPage=r.page==='collection'?'collections':r.page;$$('[data-nav],[data-mobile-nav]').forEach(a=>{const selected=(a.dataset.nav||a.dataset.mobileNav)===navPage;if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.body.dataset.page=r.page;window.scrollTo({top:0,behavior:'instant'});const c=collection(r.collection||activeCollection)||collection('walnut');document.documentElement.style.setProperty('--collection',c.palette[0]);document.title=(r.page==='home'?'Rizky Atelier':r.page==='collection'?c.name:r.page==='gallery'?'The 3D Gallery':r.page==='materials'?'The Material Library':r.page==='products'?'All Pieces':r.page==='studio'?'The Studio':'Collections')+' — The Living Gallery';
 if(r.page==='collection'){renderCollection(c);$('#collection-kind').textContent=c.kind+' / '+(['madison','trianon','wellington','nantes','belgravia'].includes(c.id)?'Reference 2023':'2026');renderReferences(c);}
 if(r.page==='products'){$('#product-collection').value=r.collection||'all';category='all';$('#product-search').value='';renderProducts();}
 if(r.page==='materials'){renderMaterials(c.id);renderMaterialReferences(c);}
 if(r.page==='gallery')renderProductReference(r.product);
 if(r.page==='gallery'){activeCollection=c.id;$('#gallery-collection').value=c.id;$('#viewer-collection').value=c.id;$('#gallery-description').textContent=c.tagline+' '+(c.productCount?c.productCount+' catalogue pieces; '+c.placementCount+' staged placements.':'A complete room study. Orbit and guided views; no catalogue SKUs.');$('#gallery-files').dataset.downloadRequest='the complete '+c.name+' project: Blender scene, models, renders and source';$('#gallery-preview').src=c.hero;$('#gallery-preview').alt=c.name+' — original Blender render preview';$('#preview-eyebrow').textContent=c.name.toUpperCase()+' / YOUR NEXT PERSPECTIVE';$('#gallery-footnote').textContent=(c.id==='walnut'?'Walnut is an orbit-only room study. ':c.layout==='furnished-interior'?'A furnished interior with complete walls and ceilings. Architectural overview is a labelled cutaway; room views restore the enclosure. Inspect loads full-detail products. ':'Exhibition meshes are optimised; Inspect loads the full-detail product. ')+'Only the chosen collection is loaded. Browser lighting differs from native Blender renders.';try{const g=await ensureGallery();if(serial!==routeSerial)return;g.setActive(true);g.configure(c,manifest.products.filter(p=>p.collection===c.id));if(r.product){if(!manifest.products.some(p=>p.collection===c.id&&p.sku===r.product)){notify('That product does not belong to this collection.');return;}await g.inspect(r.product);}else if(r.load)await g.start();}catch(error){console.error(error);notify('The 3D viewer is unavailable. Render images and contact requests remain available.');}}
}
document.querySelector('.hero-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-hero]');if(b&&manifest)setHero(b.dataset.hero);});
$('#product-collection').addEventListener('change',renderProducts);$('#product-search').addEventListener('input',renderProducts);$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;renderProducts();}));$('#clear-filters').addEventListener('click',()=>{category='all';$('#product-collection').value='all';$('#product-search').value='';renderProducts();});
$('#gallery-collection').addEventListener('change',e=>location.hash='/gallery/'+e.target.value+'?load=1');$('#viewer-collection').addEventListener('change',e=>location.hash='/gallery/'+e.target.value+'?load=1');
document.addEventListener('click',e=>{const b=e.target.closest('[data-material]');if(b)location.hash='/materials/'+b.dataset.material;const image=e.target.closest('[data-image]');if(image){lastImageTrigger=image;$('#image-full').src=image.dataset.image;$('#image-full').alt=image.dataset.caption;$('#image-caption').textContent=image.dataset.caption;$('#image-request').dataset.downloadRequest=image.dataset.request;$('#image-request').textContent=image.dataset.requestLabel||'Request original render ↗';$('#image-inspect').hidden=!image.dataset.inspect;$('#image-inspect').href=image.dataset.inspect||'#/gallery';$('#image-source-note').hidden=!image.dataset.photoSku;const sourceProduct=manifest.products.find(p=>p.sku===image.dataset.photoSku);if(sourceProduct){const photo=cataloguePhoto(sourceProduct);$('#image-source-note').textContent='Original supplied catalogue image · '+photo.size.join(' × ')+' px. Not a calibrated material sample; colours and grain may vary. '+photo.note;}$('#image-dialog').classList.toggle('is-reference',!!image.dataset.photoSku);document.dispatchEvent(new Event('atelier:modal'));$('#image-dialog').showModal();syncScroll();}});
$('#image-inspect').addEventListener('click',()=>$('#image-dialog').close());
$('#close-image').addEventListener('click',()=>$('#image-dialog').close());$('#image-dialog').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.x||e.clientX>r.right||e.clientY<r.y||e.clientY>r.bottom)e.currentTarget.close();});$('#image-dialog').addEventListener('close',()=>{syncScroll();if(lastImageTrigger?.getClientRects().length&&!lastImageTrigger.closest('[hidden]'))lastImageTrigger.focus({preventScroll:true});else $('#main').focus({preventScroll:true});});
document.addEventListener('atelier:ready',()=>{if(matchMedia('(max-width:760px)').matches&&parseRoute(location.hash).page==='gallery')$('#viewer-stage').scrollIntoView({block:'start',behavior:motion()});});window.addEventListener('hashchange',route);
try{const response=await fetch('assets/manifest.json?v=belgravia-1');if(!response.ok)throw Error('Manifest unavailable');manifest=await response.json();setupCollections();cards();renderProducts();renderStudio();setHero('belgravia');window.atelier.ready=true;await route();}catch(error){console.error(error);$('#app-status').hidden=false;$('#app-status').textContent='The collection library could not be opened. Please reload the page.';}
